/**
 * cotacaoSimuladorSolar
 */
$(document).ready(function() {
    $('[id$="txtCEP"]').mask("99999-999");

    var REGEX_EMAIL = '([a-z0-9!#$%&\'*+/=?^_`{|}~-]+(?:\.[a-z0-9!#$%&\'*+/=?^_`{|}~-]+)*@' +
        '(?:[a-z0-9](?:[a-z0-9-]*[a-z0-9])?\.)+[a-z0-9](?:[a-z0-9-]*[a-z0-9])?)';

    $('.input-email').change(function() {
        var email = $(this);
        if (email.val() != '')
            if (!IsEmailValido(email.val())) {
                alert("E-mail inválido");
                email.val("");
                Focus(email);
            }
    });

    CarregarCidadesSimulador($('[id$="dropEstadosSimulador"]').val());

    $('.input-telefone').focusout(function() {
        var objeto = $(this);
        objeto.unmask();
        var phone = objeto.val().replace(/\D/g, '');

        if (phone != '') {
            if (phone.length > 10)
                objeto.mask("(00) 90000-0000");
            else
                objeto.mask("(00) 0000-00009");

            if (!IsTelefoneValido(objeto.val())) {
                alert('Telefone inválido!');
                objeto.val('');
                Focus(objeto);
            }
        } else
            objeto.mask("(00) 0000-00009");
    }).trigger('focusout');

    $('.select-to').selectize({
        persist: false,
        maxItems: null,
        valueField: 'email',
        labelField: 'name',
        searchField: ['name', 'email'],

        render: {
            item: function(item, escape) {
                return '<div>' +
                    (item.email ? '<span class="email">' + escape(item.email) + '</span>' : '') + '</div>';
            },
            option: function(item, escape) {
                var label = item.name || item.email;
                var caption = item.name ? item.email : null;
                return '<div><span class="label">' + escape(label) + '</span></div>';
            }
        },
        createFilter: function(input) {
            var match, regex;

            // email@address.com
            regex = new RegExp('^' + REGEX_EMAIL + '$', 'i');
            match = input.match(regex);
            if (match) return !this.options.hasOwnProperty(match[0]);

            // name <email@address.com>
            regex = new RegExp('^([^<]*)\<' + REGEX_EMAIL + '\>$', 'i');
            match = input.match(regex);
            if (match) return !this.options.hasOwnProperty(match[2]);

            return false;
        },
        create: function(input) {
            if ((new RegExp('^' + REGEX_EMAIL + '$', 'i')).test(input)) {
                return {
                    email: input
                };
            }
            var match = input.match(new RegExp('^([^<]*)\<' + REGEX_EMAIL + '\>$', 'i'));
            if (match) {
                return {
                    email: match[2],
                    name: $.trim(match[1])
                };
            }
            alert('Endereço de email inválido');
            return false;
        }
    });

    $('#ctl00_ContentPlaceHolder1_cbFilial').change(function() {
        Focus($('.txtValor'));
    });

    $('.txtAddPrdCodigo').focusout(function(event) {
        CalculaPreco();
    });

    $('.txtValor').keydown(function(event) {
        if (!SomenteNumero(event))
            if (event.which != 9) {
                event.stopImmediatePropagation();
                event.stopPropagation();
                event.preventDefault();
            }
    });

    $('.txtAddPrdCodigo').keydown(function(event) {
        if (!SomenteNumero(event))
            if (event.which != 9) {
                event.stopImmediatePropagation();
                event.stopPropagation();
                event.preventDefault();
            }
    });

    $('.txtAddPrdCodigo').keyup(function(event) {
        if (event.which === 9)
            Focus($(".qtd-item-pedido"));
        else
        if (event.which != 13) {
            var valor = FormataValorNumericoAplicandoSeparadorParaDV($(this).val(), event);
            $('[id$=txtAddPrdCodigo]').val(valor);
        }
    });

    $('.dropEstadosSimulador').select2({
        placeholder: "Selecione um estado",
        cache: "true",
        allowclear: true
    });

    $('.dropCidadesSimulador').select2({
        placeholder: "Selecione uma cidade",
        cache: "true",
        allowclear: true
    });

    $('[id$="dropEstadosSimulador"]').select2().change(function() {
        var dropEstadosSimulador = $(this);
        CarregarCidadesSimulador(dropEstadosSimulador.val());
    });

    $('[id$="dropCidadesSimulador"]').select2().change(function() {
        var dropCidadeSimulador = $(this);
        $('[ID$="hfDropCidadesSimulador"]').val(parseFloat(dropCidadeSimulador.val()));
        $('[ID$="hfDescricaoCidadeSimulador"]').val($(".dropCidadesSimulador option:selected").text());
        $('[ID$="hfIncidenciaSolar"]').val(dropCidadeSimulador.val());
        $('[ID$="txtIncidenciaSolar"]').val(dropCidadeSimulador.val() + ' (Kwh/M²)');

        var consumoMensal = $('.txtConsumoMedioMensal').val();
        var potencia = Calcular(consumoMensal);

        Focus($('.txtConsumoMedioMensal100'));

        clearFields();
    });

    function CarregarCidadesSimulador(uf) {
        if (uf.length > 0) {
            BloquearTela("Carregando cidades...");
            $.ajax({
                dataType: "json",
                url: 'https://salescdn.net/static/solar-calculator/city.json',
                success: function(response) {
                    var array = response[uf];
                    DesbloquearTela();
                    var dropCidadesSimulador = $('[id$="dropCidadesSimulador"]');
                    dropCidadesSimulador.find('option').remove();
                    dropCidadesSimulador.append($("<option></option>").attr("value", "").text(""));
                    dropCidadesSimulador.select2({
                        placeholder: "Selecione uma cidade",
                        cache: "true",
                        allowclear: true,
                        data: array
                    });


                    if ($('[ID$="hfDropCidadesSimulador"]').val() > 0) {
                        $(".dropCidadesSimulador option").filter(function() {
                            return this.text == $('[ID$="hfDescricaoCidadeSimulador"]').val();
                        }).attr('selected', true);
                        $('.dropCidadesSimulador').trigger('change');
                    } else {
                        dropCidadesSimulador.select2('open');
                    }

                    clearFields();
                },
                error: function(response) {
                    var r = jQuery.parseJSON(response.responseText);
                    alert(r.Message, 'Aviso:');
                }
            });
        }
    }
});

